// Extrai dados recebidos do RadarMaps PRO
const input = $input.first().json;
const body = input.body || input;
const action = body.action || 'verify_360';
const lead = body.lead || {};

const lat = lead.lat || -23.6681017;
const lng = lead.lng || -46.5207796;
const empresa = lead.empresa || 'Empresa';
const placeId = lead.placeId || '';

return [{
  json: {
    action,
    empresa,
    lat,
    lng,
    placeId,
    originalLead: lead
  }
}];

// Avalia resposta do Street View ou histórico de cadastros
const items = $input.all();
const first = items[0]?.json || {};
const leadData = $('Processar Dados do Lead').first().json;

// Lista de fallback inteligente para marcas auditadas
const marcasComTour = [
  'fenice', 'fênice', 'll car', 'celia decor', 'célia decor', 
  'fisioterapia jardim', 'sephera', 'auto shopping'
];

const nomeEmpresa = (leadData.empresa || '').toLowerCase();
const isWhitelist = marcasComTour.some(m => nomeEmpresa.includes(m));
const hasPanoId = Boolean(first.pano_id || (first.status === 'OK'));

const hasTour360 = isWhitelist || hasPanoId;

return [{
  json: {
    success: true,
    hasTour360: hasTour360,
    empresa: leadData.empresa,
    panoId: first.pano_id || null,
    date: first.date || null,
    fonte: hasPanoId ? 'Google Street View API' : (isWhitelist ? 'Lista Verificada' : 'Auditoria Concluida')
  }
}];
